'use strict';
/**
 * CATOSHI V10 — SINGLE-FILE ROOT UPLOAD INSTALLER
 * Only this file needs uploading through GitHub 'Add files' (root directory).
 * Requires Node.js 24. Checks the current repo before any write; never touches
 * solo styles.css, game.js, wallet/database secrets, or the Dockerfile.
 * Usage: node catoshi-multiplayer-setup-v10.cjs --check
 *        node catoshi-multiplayer-setup-v10.cjs --apply
 * This file has a compressed source bundle embedded; it uses zero extra packages.
 */
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),zlib=require('node:zlib');
const root=process.cwd();
const check=process.argv.includes('--check'),apply=process.argv.includes('--apply');
if(check===apply){console.error('Use exactly one of --check or --apply');process.exit(2);}
const bundle=JSON.parse(zlib.gunzipSync(Buffer.from('','base64')).toString('utf8'));

const issues=[],notes=[],writes=new Map(),deletions=[];
function fail(s){issues.push(s)}
function has(n){return fs.existsSync(path.join(root,n))}
function read(n){return fs.readFileSync(path.join(root,n),'utf8')}
function add(n,body){writes.set(n,body)}
function replaceExactlyOnce(s,re,swap,label){const hits=[...s.matchAll(re)];if(hits.length!==1){fail(label+': expected 1 anchor, found '+hits.length);return s;}return s.replace(re,swap)}
for(const name of ['index.html','server.cjs','styles.css','game.js','package.json'])if(!has(name))fail('Missing existing Catoshi root file: '+name);
for(const name of ['catoshi-clean-actions.png','catoshi-coin.png','canyon-atmosphere.png','terrain-biomes-v1.png','terrain-obstacles-v1.png','vault-scenery-atlas.png','rush-pickups-v2.png']){
 if(!has(name))fail('Missing shared artwork in the current repo: '+name+'. Restore this existing file before installing.');
}
const bundleNames=Object.keys(bundle);
for(const name of bundleNames){
 if(!/^(catoshi-mp-[a-z0-9.-]+)$/.test(name))fail('Invalid embedded filename: '+name);
 if(has(name)&&read(name)!==bundle[name])fail('Existing '+name+' was modified: refusing to overwrite. Ask for a merge.');
}
let index='',server='',pkg=null;
if(!issues.length){
 index=read('index.html');server=read('server.cjs');try{pkg=JSON.parse(read('package.json'))}catch(e){fail('Invalid package.json: '+e.message)}
}
const panel=`\n    <!-- Catoshi multiplayer: sandboxed separately from solo gameplay -->\n    <section id="multiplayer-embedded" class="multiplayer-embedded" hidden aria-label="Multiplayer racing">\n      <div class="multiplayer-embedded-bar"><strong>CATOSHI · MULTIPLAYER</strong><button id="multiplayer-close" type="button">← BACK TO GAME</button></div>\n      <p id="multiplayer-embed-status" role="status" class="multiplayer-embed-status">Connecting to multiplayer…</p>\n      <iframe id="multiplayer-iframe" title="Catoshi multiplayer racing" src="about:blank" allow="fullscreen" referrerpolicy="strict-origin-when-cross-origin"></iframe>\n    </section>\n`;
if(pkg){
 if(!index.includes('id="mode-trial"')||!index.includes('id="mode-vault"'))fail('Expected Vault Run and Speed Trials mode buttons not found. Do not deploy.');
 if(!index.includes('id="mode-multiplayer"'))index=replaceExactlyOnce(index,/(<button\b(?=[^>]*\bid="mode-trial")[^>]*>[\s\S]*?<\/button>)/g,'$1<button id="mode-multiplayer" type="button" aria-pressed="false">MULTIPLAYER</button>','mode buttons');
 if(!index.includes('id="multiplayer-embedded"'))index=replaceExactlyOnce(index,/(?=<section\s+id="game-screen")/g,panel,'game screen');
 // If older integration was installed, switch its script to avoid double handlers.
 index=index.replace(/<script\s+defer\s+src="mp-tab\.js[^\"]*"><\/script>\s*/g,'');
 if(!index.includes('catoshi-mp-tab.js'))index=replaceExactlyOnce(index,/<\/head>/g,'  <script defer src="catoshi-mp-tab.js?v=10"></script>\n</head>','head script');
 if(!index.includes('catoshi-mp-classic.css'))index=replaceExactlyOnce(index,/<\/head>/g,'  <link rel="stylesheet" href="catoshi-mp-classic.css?v=10">\n</head>','head CSS');
 // Replace earlier V9 bridge invocation in known integration with the corrected flat bridge.
 server=server.replace(/require\(['"]\.\/mp-bridge\.cjs['"]\)/g,"require('./catoshi-mp-bridge.cjs')");
 if(!server.includes("require('./catoshi-mp-bridge.cjs').forward")){
  const hook=`\n  if(req.url==='/mp'||req.url.startsWith('/mp/')||req.url.startsWith('/mp?')){\n    try{return require('./catoshi-mp-bridge.cjs').forward(req,res)}\n    catch(e){res.writeHead(503,{'Content-Type':'application/json'});res.end('{"error":"Multiplayer temporarily unavailable"}');return}\n  }\n`;
  server=replaceExactlyOnce(server,/http\.createServer\(async\s*\(req,res\)\s*=>\s*\{/g,m=>m+hook,'HTTP createServer handler');
 }
 for(const [asset,mime] of [['catoshi-mp-classic.css','text/css'],['catoshi-mp-tab.js','text/javascript']]){
  const str="['"+asset+"','"+mime+"']";
  if(!server.includes(str))server=replaceExactlyOnce(server,/\['styles\.css','text\/css'\]/g,m=>m+','+str,'static CSS/JS map');
 }
 if(!server.includes("require('./catoshi-mp-bridge.cjs').install")){
  const init="  // Multiplayer worker runs in a different process. Its crash never terminates solo.\n  try{require('./catoshi-mp-bridge.cjs').install(app.server)}catch(e){console.error('[multiplayer] unavailable',e.message)}\n";
  server=replaceExactlyOnce(server,/^\s*app\.server\.listen\(config\.port,'0\.0\.0\.0'/gm,m=>'\n'+init+m,'server listen bootstrap');
 }
 pkg.scripts||={};
 const testCmd='node --test catoshi-mp-race.test.cjs catoshi-mp-multiplayer.test.cjs catoshi-mp-server.test.cjs catoshi-mp-inpage.test.cjs catoshi-mp-flat.test.cjs';
 if(pkg.scripts['test:multiplayer']&&!(/\bmp\//.test(pkg.scripts['test:multiplayer'])||pkg.scripts['test:multiplayer']===testCmd)){
   fail('Existing test:multiplayer script differs from known older install; refusing to overwrite.');
 } else pkg.scripts['test:multiplayer']=testCmd;
 pkg.dependencies||={};if(pkg.dependencies['socket.io']&&pkg.dependencies['socket.io']!=='4.8.1')notes.push('Existing socket.io '+pkg.dependencies['socket.io']+' preserved; check compatibility.');
 else pkg.dependencies['socket.io']='4.8.1';
 add('index.html',index);add('server.cjs',server);add('package.json',JSON.stringify(pkg,null,2)+'\n');
}
// A previous installer accidentally put a standalone-only test at the repo root.
// Archive/remove only if byte-identical to the known test (NEVER touch game.js).
const oldTest='isolation.test.cjs';
const knownStandalone=`'use strict';\nconst {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');\nconst root=__dirname;\ntest('standalone package imports none of the solo engine, wallet or payment systems',()=>{\n const pkg=require('./package.json');assert.equal(pkg.scripts.start,'node multiplayer-server.cjs');\n for(const name of ['race-fees.cjs','wallet-racing.js','solana-race.cjs','game.js','index.html','rewards.cjs','admin.cjs','online.js'])assert(!fs.existsSync(path.join(root,name)),name);\n const source=fs.readFileSync(path.join(root,'multiplayer-server.cjs'),'utf8');assert(!source.includes("require('./server.cjs')"));assert(!/SOLANA_RPC|RACE_VAULT|CATOSHI_MINT|PUBLIC_KEY|walletAddress/.test(source));\n const html=fs.readFileSync(path.join(root,'multiplayer.html'),'utf8');assert(!/payment|entry fee|wallet connect|token transfer/i.test(html));\n});\n`;
if(has(oldTest)){
 const original=read(oldTest),normalize=s=>s.replace(/\r\n/g,'\n').trim();
 if(normalize(original)===normalize(knownStandalone)){
  notes.push('Will back up and remove the misplaced standalone-only isolation.test.cjs from root.');deletions.push(oldTest);
 }else notes.push('Unrecognized root isolation.test.cjs left untouched. Review its test assumptions if npm test fails.');
}
for(const [n,body] of Object.entries(bundle))add(n,body);
if(issues.length){issues.forEach(s=>console.error('BLOCKED:',s));console.error('No files changed.');process.exit(1)}
for(const [n,b] of writes){if(!has(n)||read(n)!==b)notes.push('UPDATE: '+n)}
notes.push('PRESERVED: game.js, styles.css, Dockerfile, main data and rewards');
if(has('Dockerfile')&&!/RUN\s+npm\s+(?:ci|install)/.test(read('Dockerfile')))notes.push('WARNING: Dockerfile has no npm install step — ask agent to address before deploy.');
notes.forEach(s=>console.log(s));
if(check){console.log('CHECK PASSED: no changes made. Next: node catoshi-multiplayer-setup-v10.cjs --apply');process.exit(0)}
const backupDir=path.join(root,'.catoshi-mp-backups','flat-v10-'+new Date().toISOString().replace(/[:.]/g,'-'));
fs.mkdirSync(backupDir,{recursive:true});
try{
 for(const n of new Set([...writes.keys(),...deletions]))if(has(n))fs.copyFileSync(path.join(root,n),path.join(backupDir,n));
 // All potentially failing validations happen above, before the first write.
 for(const [n,b] of writes){if(has(n)&&read(n)===b)continue;const tmp=path.join(root,n+'.flat-v10.tmp');fs.writeFileSync(tmp,b);fs.renameSync(tmp,path.join(root,n))}
 for(const n of deletions)fs.unlinkSync(path.join(root,n));
 const ign=path.join(root,'.gitignore');const current=fs.existsSync(ign)?fs.readFileSync(ign,'utf8'):'';
 if(!current.includes('.catoshi-mp-backups/'))fs.appendFileSync(ign,'\n.catoshi-mp-backups/\n');
 console.log('APPLIED: flat root files installed; backups in '+path.relative(root,backupDir));
 console.log('NEXT: npm install && npm test && npm run test:multiplayer && git diff --check');
 console.log('IMPORTANT: commit generated changes to GitHub. Railway runtime changes alone are temporary.');
}catch(e){console.error('WRITE FAILED:',e.message);console.error('Backups kept at '+backupDir+'; use them to restore any partial changes.');process.exit(1)}
